  function renderDashboard() {
    // Для админа: фильтр по участку (null = все участки)
    var dashFilterArea = S.dashArea;
    var dashCanFilter = (S.role === 'admin' || S.role === 'nach' || S.role === 'viewer'); // включая начальника СЭОГС
    function dashMastersAll() {
      // Админ, начальник участка и начальник СЭОГС на дашборде видят ВСЕ участки (с возможностью выбора); прочие — свой
      var all = dashCanFilter ? getMasters() : visibleMasters();
      if (dashCanFilter && dashFilterArea) return all.filter(function (m) { return m.area === dashFilterArea; });
      return all;
    }
    // 22.09-193: если выбранный в «КПД мастеров» мастер выпал из списка (сменили участок) — выбор сбрасывается
    if (S.dashMaster && !dashMastersAll().some(function (m) { return String(m.id) === String(S.dashMaster); })) S.dashMaster = null;
    function dashMasters() {
      var all = dashMastersAll();
      if (S.dashMaster) all = all.filter(function (m) { return String(m.id) === String(S.dashMaster); }); // 22.09-193: один мастер
      return all;
    }
    function dashTasks() {
      var dm = dashMasters(); var ids = {};
      dm.forEach(function (m) { ids[m.id] = 1; });
      return S.tasks.filter(function (t) { return ids[t.m]; });
    }

    var vt = dashTasks();
    var today = vt.filter(function (t) { return t.d === 0; });
    var redzone = vt.filter(function (t) { return !isDone(t) && (t.dl <= 2 || t.d < 0); }).sort(function (a, b) { return a.dl - b.dl; });

    var mastersToday = dashMasters();
    var overloads = mastersToday.filter(function (m) { return loadForDay(m.id, 0) > masterCapacity(m.id, 0); }).length;
    var doneMonth = 0, totalMonth = 0;
    vt.forEach(function (t) {
      var d = offToDate(t.d);
      if (d.getMonth() === TODAY.getMonth() && d.getFullYear() === TODAY.getFullYear()) { totalMonth++; if (isDone(t)) doneMonth++; }
    });
    var pct = totalMonth ? Math.round(doneMonth / totalMonth * 100) : 0;

    var areas = {};
    vt.forEach(function (t) {
      var d = offToDate(t.d);
      if (d.getMonth() !== TODAY.getMonth() || d.getFullYear() !== TODAY.getFullYear()) return;
      var m = masterById(t.m); if (!m) return;
      areas[m.area] = areas[m.area] || { done: 0, total: 0 };
      areas[m.area].total++; if (isDone(t)) areas[m.area].done++;
    });

    var html = '';

    // === Селектор участка для админа, начальника участка и начальника СЭОГС ===
    if (dashCanFilter) {
      html += '<div style="margin-bottom:16px;display:flex;gap:10px;align-items:center;flex-wrap:wrap">';
      html += '<label style="font-size:12px;font-weight:600;color:var(--muted)">Участок:</label>';
      html += '<select id="dash-area" style="padding:8px 12px;border:1px solid var(--line);border-radius:9px;font-size:13px;font-family:inherit;background:var(--card)">';
      html += '<option value=""' + (!dashFilterArea ? ' selected' : '') + '>Все участки</option>';
      var _dashAreas = areasList();
      _dashAreas.forEach(function (a) { html += '<option value="' + esc(a) + '"' + (dashFilterArea === a ? ' selected' : '') + '>' + esc(a) + '</option>'; });
      html += '</select>';
      if (dashFilterArea) {
        html += '<button class="btn sm" data-action="dash-area-clear">Сбросить</button>';
      }
      html += '</div>';
    }

    // 22.09-193: право выбирать мастера для просмотра КПД — админ, начальник СЭОГС, начальник участка, старший мастер.
    // 22.09-199: сам выпадающий список перенесён с верха страницы в заголовок карточки «⚡ КПД мастеров» (см. _dashJoin ниже)
    var dashCanPickMaster = (S.role === 'admin' || S.role === 'viewer' || S.role === 'nach' || S.role === 'smaster');

    html += '<div class="kpi-row">';
    html += kpi(today.length, 'Задач на сегодня', 'по ' + mastersToday.filter(function (m) { return today.some(function (t) { return String(t.m) === String(m.id); }); }).length + ' мастера(ам)', '#2563eb', 'kpi-today'); // 22.09-187: мастера без задач сегодня не считаем
    html += kpi(overloads, 'Перегрузок сегодня', 'превышение фонда рабочего времени', '#dc2626', 'kpi-overloads');
    html += kpi(pct + '%', 'Выполнено за месяц', doneMonth + ' из ' + totalMonth + ' работ', '#16a34a', 'kpi-month');
    // KPI УБиРОГС
    var permitCount = vt.filter(function(t) { return t.needs_permit && !isDone(t); }).length;
    var weatherCount = vt.filter(function(t) { var w = workOf(t); var wf = getWeatherForecast(t.d); return w && w.min_temp > -50 && wf && wf.temp != null && wf.temp < w.min_temp; }).length;
    html += kpi(permitCount, 'Ордеров истекает', 'работы с разрешениями', '#f59e0b', 'kpi-permits');
    // 22.09-171: «Красная зона» — пятая кнопка в ряду KPI (как прочие — по нажатию список задач зоны)
    html += kpi(redzone.length, 'Красная зона', 'предельный срок ≤ 2 дн', '#dc2626', 'kpi-redzone');
    html += '</div>';

    // Оповещения УБиРОГС
    if (permitCount > 0) {
      html += '<div class="permit-warn">📋 <b>Внимание:</b> ' + permitCount + ' задач с действующими ордерами. Проверьте сроки истечения разрешений в разделе «Отчёты».</div>';
    }
    if (weatherCount > 0) {
      html += '<div class="weather-warn">🌡️ <b>Погодные ограничения:</b> ' + weatherCount + ' задач не могут быть выполнены из-за несоответствия температуры.</div>';
    }
    // Информация о погоде из прогноза
    var todayWeather = getWeatherForecast(0);
    if (!todayWeather) {
      todayWeather = { temp: '—', desc: 'Загрузка...', snow: false, snowfall: 0 };
    }
    var snowExpected = '';
    for (var off = 1; off <= 7; off++) {
      var wf = getWeatherForecast(off);
      if (wf && wf.snow && wf.snowfall > 0.1) {
        snowExpected = ' · ❄️ Снег ожидается ' + fmtShort(off) + ' (' + wf.snowfall + ' мм)';
        break;
      }
    }
    var wIcon = todayWeather.snow ? '❄️' : todayWeather.desc.indexOf('Дождь') !== -1 || todayWeather.desc.indexOf('Морось') !== -1 ? '🌧️' : todayWeather.desc === 'Ясно' ? '☀️' : '⛅';
    var _wx = weatherSceneHTML(todayWeather, { hour: new Date().getHours(), leftFade: true });
    html += '<div data-action="open-weather" style="margin-bottom:0;padding:14px 18px;min-height:68px;background:#1e3a5f;color:#fff;border-radius:10px;display:flex;align-items:center;gap:12px;cursor:pointer;transition:transform .2s,box-shadow .2s;position:relative;overflow:hidden;" onmouseover="this.style.transform=\'translateY(-2px)\';this.style.boxShadow=\'0 8px 24px rgba(0,0,0,.3)\';" onmouseout="this.style.transform=\'\';this.style.boxShadow=\'\';" title="Нажмите для просмотра прогноза на 15 дней">';
    html += _wx.html;
    html += '<span style="font-size:28px;position:relative;z-index:1;text-shadow:0 1px 5px rgba(0,0,0,.35);">' + wIcon + '</span>';
    html += '<div style="position:relative;z-index:1;text-shadow:0 1px 5px rgba(0,0,0,.35);"><div style="font-size:15px;font-weight:700;">' + todayWeather.temp + '°C · ' + todayWeather.desc + '</div>';
    html += '<div style="font-size:11px;color:#e2e8f0;">Погода: Минск · ' + fmt(TODAY) + snowExpected + '</div></div>';
    html += '<button class="wx-map-fab" data-action="open-wx-map" title="Открыть карту погоды Минска и Минской области">🗺 Карта погоды</button>';
    html += '</div>';
    // Выпадающий список при нажатии
    html += '<div id="weather-dropdown" class="weather-dropdown"></div>';
    // Отступ перед панелью аналитики
    html += '<div style="height:16px;"></div>';

    // 22.09-173: «Панель аналитики» удалена с панели мониторинга (выбор месяца — кнопкой-календарём в «⚡ КПД мастеров»)

    // === ГРАФИКИ (SVG, без библиотек; учитывают выбранный участок — dashTasks/dashMasters) ===
    // 1) План/факт по дням текущего месяца; 2) КПД мастеров (22.09-166)
    var _dashJoin = ''; // 22.09-169: одна общая карточка «⚡ КПД мастеров + 📈 Выполнение по дням» (собирает dashCharts)
    (function dashCharts() {
      var cmy = getDashMY(); // 22.09-171: график по дням — за месяц, выбранный календариком КПД
      var dim = new Date(cmy.y, cmy.m + 1, 0).getDate();
      var plan = [], fact = [];
      for (var dd = 1; dd <= dim; dd++) {
        var dOff = dateToOff(new Date(cmy.y, cmy.m, dd));
        var dts = vt.filter(function (t) { return t.d === dOff; });
        plan.push(dts.length);
        fact.push(dts.filter(isDone).length);
      }
      var maxV = Math.max.apply(null, plan.concat(fact, [1]));
      var W = 760, H = 210, L = 30, B = 20, T = 22; // T — запас над столбиками под цифры
      var bw = (W - L - 8) / dim;
      var bars = '', grid = '', nums = '';
      // 22.09-188: график растягивается по высоте карточки (SVG с preserveAspectRatio="none"),
      // поэтому ВСЕ цифры — HTML-слой поверх SVG с %-позициями: шрифт больше не искажается
      [0, 0.5, 1].forEach(function (f) {
        var gy = T + Math.round((H - T - B) * (1 - f));
        grid += '<line x1="' + L + '" y1="' + gy + '" x2="' + (W - 4) + '" y2="' + gy + '" stroke="#64748b" stroke-opacity=".35" stroke-width="1"/>';
        nums += '<span style="position:absolute;left:0;width:' + (L - 4) + 'px;text-align:right;bottom:' + ((H - gy - 4) / H * 100).toFixed(2) + '%;font-size:10px;color:#94a3b8;line-height:1">' + Math.round(maxV * f) + '</span>';
      });
      for (var bi = 0; bi < dim; bi++) {
        var bx = L + bi * bw;
        var hP = Math.round((H - T - B) * plan[bi] / maxV);
        var hF = Math.round((H - T - B) * fact[bi] / maxV);
        var bwid = Math.max(1, bw - 2).toFixed(1);
        var xC = ((bx + bw / 2) / W * 100).toFixed(3);
        bars += '<rect x="' + (bx + 1).toFixed(1) + '" y="' + (H - B - hP) + '" width="' + bwid + '" height="' + Math.max(hP, 0) + '" rx="2" fill="#bfdbfe"><title>' + (bi + 1) + ' ' + MON[cmy.m] + ': план ' + plan[bi] + ' задач</title></rect>';
        if (fact[bi] > 0) bars += '<rect x="' + (bx + 1).toFixed(1) + '" y="' + (H - B - hF) + '" width="' + bwid + '" height="' + Math.max(hF, 0) + '" rx="2" fill="#16a34a"><title>' + (bi + 1) + ' ' + MON[cmy.m] + ': выполнено ' + fact[bi] + '</title></rect>';
        // цифра количества задач дня — над столбиком (только дни с задачами); HTML — не растягивается
        if (plan[bi] > 0) nums += '<span style="position:absolute;left:' + xC + '%;transform:translateX(-50%);bottom:' + ((B + hP + 5) / H * 100).toFixed(2) + '%;font-size:10.5px;font-weight:800;color:#1e40af;line-height:1;pointer-events:none">' + plan[bi] + '</span>';
        if ((bi + 1) % 5 === 0 || bi === 0) nums += '<span style="position:absolute;left:' + xC + '%;transform:translateX(-50%);bottom:2px;font-size:10px;color:#64748b;line-height:1;pointer-events:none">' + (bi + 1) + '</span>';
      }
      var svg1 = '<svg viewBox="0 0 ' + W + ' ' + H + '" preserveAspectRatio="none" style="position:absolute;left:0;top:0;width:100%;height:100%;display:block" xmlns="http://www.w3.org/2000/svg">' + grid + bars + '</svg>';
      var chart1 = '<div style="position:relative;flex:1;min-height:190px">' + svg1 + nums + '</div>';

      /* 22.09-166: вместо «Загрузка мастеров сегодня» — карточка «⚡ КПД мастеров»
         (та же метрика, что в панели аналитики — выбранный там месяц, —
         но в светлом виде соседних блоков «Выполнение по дням»/«Сегодня») */
      var kMY = getDashMY();
      var kTasks = vt.filter(function (t) { var dd = offToDate(t.d); return dd.getMonth() === kMY.m && dd.getFullYear() === kMY.y; });
      var kWorkH = 0, kTravelMin = 0, kTravelCnt = 0;
      kTasks.forEach(function (t) {
        kWorkH += taskHours(t);
        var tmin = taskTravelMin(t);
        if (tmin <= 0) tmin = estimateTravelMin(t);   // нет расчёта маршрута — оценка по расстоянию
        if (tmin > 0) { kTravelMin += tmin; kTravelCnt++; }
      });
      var kTravelH = kTravelMin / 60;
      var kTotalH = kWorkH + kTravelH;
      var kPctObj = kTotalH > 0 ? (kWorkH / kTotalH * 100) : 0;
      var kPctRoad = kTotalH > 0 ? (kTravelH / kTotalH * 100) : 0;
      var kAvgTravel = kTravelCnt > 0 ? Math.round(kTravelMin / kTravelCnt) : 0;
      var kDec = function (x) { return (Math.round(x * 10) / 10).toString().replace('.', ','); };
      var kpdBar = (kTotalH > 0)
        ? '<div style="display:flex;height:16px;border-radius:8px;overflow:hidden;background:#eef2f7;border:1px solid #cbd5e1">' +
          '<div style="width:' + kPctObj.toFixed(1) + '%;background:#2563eb" title="Работа на объектах: ' + kDec(kPctObj) + '%"></div>' +
          '<div style="width:' + kPctRoad.toFixed(1) + '%;background:#f59e0b" title="В пути: ' + kDec(kPctRoad) + '%"></div></div>'
        : '<div style="height:16px;border-radius:8px;background:#eef2f7;border:1px dashed #cbd5e1"></div>';
      var kpdBody =
        '<div style="display:flex;align-items:center;gap:16px;flex-wrap:wrap">' +
          '<div style="text-align:center;min-width:96px"><div style="font-size:30px;font-weight:800;color:#1d4ed8;line-height:1.05">' + (kTotalH > 0 ? kDec(kPctObj) : '—') + '%</div>' +
          '<div style="font-size:11px;font-weight:600;color:var(--muted);margin-top:2px">на объектах</div></div>' +
          '<div style="flex:1;min-width:190px">' + kpdBar +
            '<div style="display:flex;gap:14px;flex-wrap:wrap;margin-top:6px;font-size:11px;font-weight:700">' +
              '<span style="color:#1d4ed8">■ Работа на объектах: ' + fmtH(kWorkH) + ' ч</span>' +
              '<span style="color:#b45309">■ В пути: ' + fmtH(kTravelH) + ' ч</span>' +
            '</div></div></div>' +
        '<div style="margin-top:10px;font-size:11.5px;color:var(--muted)">🚗 В пути за ' + esc(dashMonthLabel().toLowerCase()) + ': <b style="color:var(--ink)">' + (kTotalH > 0 ? kDec(kPctRoad) : '0') + '%</b> от всего времени (' + fmtH(kTotalH) + ' ч) · Среднее время переезда: <b style="color:var(--ink)">≈ ' + kAvgTravel + ' мин</b></div>';

      // 22.09-199: выбор мастера для просмотра КПД — прямо в заголовке этой карточки (блок справа внизу)
      // (тот же id dash-master: привязка события — в конце renderDashboard; выбор влияет на расчёт КПД ниже и весь дашборд)
      var kpdMasterSel = '';
      if (dashCanPickMaster) {
        kpdMasterSel = '<select id="dash-master" title="Показатели панели, списки KPI и блок «Сегодня» — по выбранному мастеру или по всем сразу" style="padding:5px 10px;border:1px solid var(--line);border-radius:9px;font-size:12.5px;font-weight:700;font-family:inherit;background:var(--card);color:var(--ink);max-width:230px;cursor:pointer">';
        kpdMasterSel += '<option value=""' + (!S.dashMaster ? ' selected' : '') + '>👷 Все мастера</option>';
        dashMastersAll().forEach(function (m) { kpdMasterSel += '<option value="' + esc(m.id) + '"' + (S.dashMaster && String(S.dashMaster) === String(m.id) ? ' selected' : '') + '>' + esc(m.name) + (m.area ? ' · ' + esc(m.area) : '') + '</option>'; });
        kpdMasterSel += '</select>';
      }
      // 22.09-169: «КПД мастеров» и «Выполнение по дням» — ОДНА карточка:
      // сверху метрика КПД, под ней через разделитель — график по дням
      // 22.09-171: в заголовке — календарик выбора месяца (та же кнопка, что в панели аналитики);
      // «Выполнение по дням» — за тот же выбранный месяц; график занимает всю свободную высоту карточки
      _dashJoin = '<div class="card" style="display:flex;flex-direction:column;height:100%"><div class="card-h" style="flex:none"><h2>⚡ КПД мастеров</h2><div class="spacer"></div>' + kpdMasterSel + '<button type="button" data-action="dash-month-toggle" title="Выбрать месяц для расчёта КПД и графика по дням" style="display:inline-flex;align-items:center;gap:6px;border:1px solid var(--line);background:var(--card);color:var(--ink);font-weight:700;font-family:inherit;border-radius:9px;padding:5px 12px;cursor:pointer;font-size:12.5px;white-space:nowrap">📅 ' + esc(dashMonthLabel()) + '</button></div><div class="card-b" style="flex:1;display:flex;flex-direction:column;min-height:0">' + kpdBody +
        '<div style="margin-top:14px;padding-top:11px;border-top:1px dashed var(--line);flex:1;display:flex;flex-direction:column;min-height:0">' +
          '<div style="display:flex;align-items:baseline;gap:10px;flex-wrap:wrap;margin-bottom:4px;flex:none"><span style="font-size:13.5px;font-weight:800;color:var(--ink)">📈 Выполнение по дням</span><span style="font-size:11.5px;color:var(--muted);font-weight:600">' + MON_NOM[cmy.m] + ' ' + cmy.y + ' · <span style="color:#2563eb;font-weight:700">■ план</span> <span style="color:#16a34a;font-weight:700">■ выполнено</span></span></div>' +
          chart1 +
        '</div></div></div>';
    })();

    // 22.09-171: календарик выбора даты — блок показывает работы на любой выбранный день
    var dayOff = (typeof S.dashDayOff === 'number' && isFinite(S.dashDayOff)) ? Math.round(S.dashDayOff) : 0;
    var dayDate = offToDate(dayOff);
    var dayTask = vt.filter(function (t) { return t.d === dayOff; });
    var mastersDay = mastersToday.filter(function (m) { return dayTask.some(function (t) { return String(t.m) === String(m.id); }); }); // 22.09-187: только мастера С задачами; 22.09-188: id — строками
    var overloadsDay = mastersDay.filter(function (m) { return loadForDay(m.id, dayOff) > masterCapacity(m.id, dayOff); }).length;

    html += '<div class="dash-grid">';
    html += '<div class="card"><div class="card-h"><h2>' + (dayOff === 0 ? 'Сегодня' : esc(fmt(dayDate))) + '</h2><span class="sub" style="display:flex;align-items:center;gap:6px"><input type="date" id="dash-day-sel" value="' + key(dayDate) + '" title="Выбрать дату для просмотра работ" style="padding:4px 8px;border:1px solid var(--line);border-radius:8px;font-size:12px;font-family:inherit;background:var(--card);color:var(--ink)">' + (dayOff !== 0 ? '<button type="button" class="btn sm" data-action="dash-day-today" title="Вернуться на сегодня">Сегодня</button>' : '') + '</span><div class="spacer"></div><span class="badge tag ' + (overloadsDay ? 'over' : 'ok') + '">' + (overloadsDay ? 'Есть перегрузки' : 'Без перегрузок') + '</span></div><div class="card-b">';
    if (!dayTask.length) html += '<div class="empty">' + (dayOff === 0 ? 'На сегодня задач нет' : 'На ' + esc(fmt(dayDate)) + ' задач нет') + '</div>';
    mastersDay.forEach(function (m) {
      var mt = dayTask.filter(function (t) { return String(t.m) === String(m.id); }); // 22.09-188: id — строками
      var load = mt.reduce(function (s, t) { return s + (isDone(t) ? 0 : taskHours(t)); }, 0);
      var inProg = mt.filter(function (t) { return t.started_at && !isDone(t); })[0]; // 22.09-190: сейчас работает на объекте
      var _mc = masterCapacity(m.id, dayOff);
      var over = load > _mc;
      html += '<div class="today-mstr"><span class="dot" style="background:' + m.color + '"></span><div><div class="nm" data-action="wc-open" data-mid="' + esc(m.id) + '" style="cursor:pointer" title="Нажмите — откроются карточки всех работ на этот день">' + esc(m.name) + ' <span style="color:var(--muted);font-weight:600;font-size:11px">→</span></div><div class="ar">' + esc(m.area) + '</div></div><div class="meta"><div class="h" style="color:' + (over ? 'var(--red)' : 'var(--ink)') + '">' + fmtH(load) + ' ч / ' + fmtH(_mc) + ' ч</div><span class="tag ' + (over ? 'over' : 'ok') + '">' + (over ? '⚠ Перегрузка +' + fmtH(load - _mc) + ' ч' : mt.length + ' заданий') + '</span>' + (dayOff === 0 && inProg ? ' <span class="tag ok" style="background:#dcfce7;color:#166534" title="Работа начата в ' + fmtClock(inProg.started_at) + '">🔨 на объекте с ' + fmtClock(inProg.started_at) + '</span>' : '') + '</div></div>';
      // гант-шкала дня: 8:00–20:00, задачи и переезды
      html += ganttDayHtml(m, dayOff);
      mt.slice(0, 4).forEach(function (t) {
        var o = OBJ_MAP[t.o], w = workOf(t);
        html += '<div class="taskline"><span class="pill">' + esc(w ? w.name : '?') + '</span><span>' + esc(addrOf(t)) + '</span>' + taskDayCtlHtml(t, dayOff) + '<span style="margin-left:auto;color:var(--muted)">' + fmtH(taskHours(t)) + ' ч</span></div>';
      });
      if (mt.length > 4) html += '<div class="taskline" style="color:var(--muted)">и ещё ' + (mt.length - 4) + '…</div>';
    });
    html += '</div></div>';
    html += _dashJoin; // 22.09-169: общая карточка «КПД мастеров + Выполнение по дням» — рядом с «Сегодня»
    html += '</div>';

    view.innerHTML = html;
    animKpiNumbers(); // цифры KPI «накручиваются»
    document.getElementById('rz-badge').textContent = redzone.length;

    // привязка селектора участка (для админа)
    var dashAreaSel = document.getElementById('dash-area');
    if (dashAreaSel) dashAreaSel.addEventListener('change', function (e) { S.dashArea = e.target.value || null; renderDashboard(); });
    // 22.09-193: привязка селектора «КПД мастеров»
    var dashMasterSel = document.getElementById('dash-master');
    if (dashMasterSel) dashMasterSel.addEventListener('change', function (e) { S.dashMaster = e.target.value || null; renderDashboard(); });
    // 22.09-171: календарик выбора даты в блоке «Сегодня»
    var dashDaySel = document.getElementById('dash-day-sel');
    if (dashDaySel) dashDaySel.addEventListener('change', function (e) {
      var v = e.target.value;
      if (!v) { S.dashDayOff = 0; renderDashboard(); return; }
      var parts = v.split('-');
      S.dashDayOff = dateToOff(new Date(+parts[0], +parts[1] - 1, +parts[2]));
      renderDashboard();
    });
    // Запуск случайных вспышек молний, если сегодня гроза (сцена содержит #wx-bolts)
    setupLightning();
  }

  function kpi(val, lab, hint, color, action) {
    var clickAttr = action ? ' data-action="' + action + '" style="cursor:pointer"' : '';
    return '<div class="kpi"' + clickAttr + '><div class="acc" style="background:' + color + '"></div><div class="lab">' + lab + '</div><div class="val">' + val + '</div><div class="hint">' + hint + '</div></div>';
  }

  /* ===== ГАНТ-ШКАЛА ДНЯ МАСТЕРА (8:00–20:00): задачи + переезды ===== */
  // Конец гант-шкалы дня: 8-часовой день — 8:00–20:00, 12-часовой — 8:00–21:00
  // (у 12-часовика рабочий день законно заканчивается после 20:00 — «везде по 12»)
  function ganttDayEndMin(m) { return 480 + (wkData(m.id).hours === 12 ? 13 : 12) * 60; }
  function ganttBlock(from, min, color, title, op, endMin) {
    if (min <= 0) return '';
    var span = (endMin || 1200) - 480;
    var l = (from - 480) / span * 100, w = min / span * 100;
    return '<span style="position:absolute;top:2px;bottom:2px;left:' + l.toFixed(2) + '%;width:' + Math.max(0.4, w).toFixed(2) + '%;border-radius:3px;background:' + color + (op != null ? ';opacity:' + op : '') + '" title="' + esc(title) + '"></span>';
  }
  /* Гант-шкала дня мастера — ТОТ ЖЕ движок, что и карта местоположения:
     порядок объезда (ближайший сосед от базы) и реальные времена переездов
     от единого роутера BRouter car (economic) с учётом пробок (кэш sessionStorage).
     Если кэша нет — оценка по расстояниям и фоновый запрос роутера: когда придёт,
     дашборд перерисуется и числа совпадут с картой местоположения точно.
     Выезд с базы в 8:30. */
  function ganttDayHtml(m, dayOff) {
    try {
      var tasks = S.tasks.filter(function (t) { return t.m === m.id && t.d === dayOff; });
      if (!tasks.length) return '';
      var base = currentBase();
      // координаты точек — приоритет как на livemap (задача → объект → кэш геокодера)
      var pts = [], allGeo = true;
      tasks.forEach(function (t) {
        // приоритет координат — КАК НА КАРТЕ МЕСТОПОЛОЖЕНИЯ (lmBuildRoute):
        // сначала координаты задачи, затем объект справочника, затем кэш геокодера
        var o = OBJ_MAP[t.o];
        var lat = (t.lat != null) ? t.lat : ((o && o.lat != null) ? o.lat : null);
        var lng = (t.lng != null) ? t.lng : ((o && o.lng != null) ? o.lng : null);
        if (lat == null) {
          try { var c = getTaskCoords(t.addr); if (c) { lat = c.lat; lng = c.lng; } } catch (e) {}
        }
        if (lat == null || lng == null) allGeo = false;
        pts.push({ t: t, lat: lat, lng: lng, hours: taskHours(t), addr: addrOf(t) });
      });
      if (!allGeo) return ganttDayEstHtml(m, tasks); // нет координат — упрощённая оценка
      var ordered = lmNearestOrder(pts, base);
      // OSRM-кэш карты местоположения (тот же ключ) — точные числа без запросов
      var res = null;
      try {
        var raw = sessionStorage.getItem(lmOsrmCacheKey(m, ordered, base, dayOff));
        if (raw) {
          var c = JSON.parse(raw);
          if (c && c.res && (Date.now() - c.ts) < 6 * 3600 * 1000) res = c.res;
        }
      } catch (e) {}
      if (!res) {
        // кэша нет: оценка по расстояниям (те же коэффициенты, что estimateTravelMin)
        var legs = [], cur = base, sumKm = 0, sumMin = 0;
        var seq = ordered.concat([base]); // …и возврат на базу
        seq.forEach(function (p) {
          var km = distKm(cur, p) * 1.4;
          var min = Math.max(3, Math.round(km / 35 * 60));
          legs.push({ distance: km * 1000, duration: min * 60 });
          sumKm += km; sumMin += min; cur = p;
        });
        res = { ok: true, legs: legs, km: sumKm, min: sumMin };
        wkGanttFetchOsrm(m, ordered, base, dayOff); // фоном подтянуть точные числа у OSRM
      }
      var opt = lmOrderByWaypoints(ordered, res);
      var sched = lmSchedCore(opt, res);
      return ganttFromSchedHtml(m, sched);
    } catch (e) { return ''; }
  }

  // Отрисовка ганта из расписания (движок livemap): drive = серый, stay = задача
  function ganttFromSchedHtml(m, sched) {
    var T1 = ganttDayEndMin(m), blocks = '', end = 0; // окно шкалы — по часам мастера (8/12)
    sched.evs.forEach(function (ev) {
      if (ev.type === 'drive') {
        var ttl = ev.dest
          ? ('🚗 Переезд: ' + (ev.dest.addr || '') + ' · ' + fmtDuration(ev.min))
          : ('🚗 Возврат на базу · ' + fmtDuration(ev.min));
        blocks += ganttBlock(ev.t0, ev.min, '#94a3b8', ttl, .45, T1);
      } else {
        var t = ev.pt.t, w = workOf(t);
        blocks += ganttBlock(ev.t0, ev.min, isDone(t) ? '#16a34a' : (m.color || '#2563eb'),
          (w ? w.name : '?') + ' · ' + fmtH(ev.min / 60) + ' ч' + (isDone(t) ? ' ✓ выполнено' : ''), isDone(t) ? .95 : .6, T1);
      }
      end = Math.max(end, ev.t0 + ev.min);
    });
    var s = '<div style="position:relative;height:18px;border-radius:6px;background:var(--panel-3);margin:7px 0 2px;overflow:hidden" title="Гант дня (выезд с базы в 8:30, как на карте местоположения): цветные — задачи, серые — переезды">';
    s += blocks;
    if (end > T1) s += '<span style="position:absolute;right:3px;top:2px;font-size:9px;color:var(--red);font-weight:800">▸ ' + lmFmtTime(T1) + '+</span>';
    s += '</div>';
    return s;
  }

  // Запасной вариант без координат: последовательная оценка (без OSRM)
  function ganttDayEstHtml(m, tasks) {
    var T1 = ganttDayEndMin(m), cur = 8 * 60, blocks = '', over = false; // окно шкалы — по часам мастера (8/12)
    tasks.sort(function (a, b) { return (a.dl - b.dl) || (taskHours(b) - taskHours(a)); });
    tasks.forEach(function (t) {
      var w = workOf(t);
      var tv = t.travelMin != null ? t.travelMin : estimateTravelMin(t);
      if (!tv || tv < 0 || !isFinite(tv)) tv = 15;
      if (cur < T1) blocks += ganttBlock(cur, Math.min(tv, T1 - cur), '#94a3b8', '🚗 Переезд ~' + fmtDuration(tv), .45, T1);
      cur += tv;
      var h = Math.round(taskHours(t) * 60);
      if (cur < T1) blocks += ganttBlock(cur, Math.min(h, T1 - cur), isDone(t) ? '#16a34a' : (m.color || '#2563eb'),
        (w ? w.name : '?') + ' · ' + fmtH(taskHours(t)) + ' ч' + (isDone(t) ? ' ✓ выполнено' : ''), isDone(t) ? .95 : .6, T1);
      cur += h;
      if (cur > T1) over = true;
    });
    var s = '<div style="position:relative;height:18px;border-radius:6px;background:var(--panel-3);margin:7px 0 2px;overflow:hidden" title="Гант дня (оценка: координаты части задач неизвестны)">';
    s += blocks;
    if (over) s += '<span style="position:absolute;right:3px;top:2px;font-size:9px;color:var(--red);font-weight:800">▸ ' + lmFmtTime(T1) + '+</span>';
    s += '</div>';
    return s;
  }

  // Фоновый запрос OSRM для ганта (мягкая очередь, кэш livemap) + перерисовка дашборда
  var wkOsrmQueue = [], wkOsrmBusy = false, wkOsrmPending = {}, wkOsrmRerender = null;
  function wkGanttFetchOsrm(m, ordered, base, dayOff) {
    try {
      var key = lmOsrmCacheKey(m, ordered, base, dayOff);
      if (wkOsrmPending[key]) return;
      wkOsrmPending[key] = 1;
      wkOsrmQueue.push({ m: m, ordered: ordered, base: base, key: key, dayOff: dayOff });
      wkOsrmNext();
    } catch (e) {}
  }
  function wkOsrmNext() {
    if (wkOsrmBusy || !wkOsrmQueue.length) return;
    var job = wkOsrmQueue.shift();
    wkOsrmBusy = true;
    lmOsrmCached(job.m, job.ordered, job.base, function (res) {
      delete wkOsrmPending[job.key];
      wkOsrmBusy = false;
      if (res && res.ok && S.screen === 'dashboard') {
        if (wkOsrmRerender) clearTimeout(wkOsrmRerender);
        wkOsrmRerender = setTimeout(function () {
          wkOsrmRerender = null;
          if (S.screen === 'dashboard') renderDashboard(); // теперь — точные числа
        }, 250);
      }
      setTimeout(wkOsrmNext, 300); // мягкая пауза между запросами к OSRM
    }, job.dayOff);
  }

  // Ось времени для гант-шкал (одна на карточку «Сегодня»)
  /* ===== ЖИВЫЕ KPI: цифры «накручиваются» при отрисовке дашборда ===== */
  function animKpiNumbers() {
    try {
      document.querySelectorAll('.kpi .val').forEach(function (el) {
        var txt = el.textContent || '';
        var mm = /^([\d]+)(.*)$/.exec(txt);
        if (!mm) return;
        var target = parseInt(mm[1], 10);
        if (!isFinite(target) || target <= 0) return;
        var suffix = mm[2];
        var t0 = null, DUR = 650;
        function step(ts) {
          try {
            if (t0 === null) t0 = ts;
            var k = Math.min(1, (ts - t0) / DUR);
            var ke = 1 - Math.pow(1 - k, 3);
            el.textContent = Math.round(target * ke) + suffix;
            if (k < 1) requestAnimationFrame(step);
            else el.textContent = txt;
          } catch (e) { el.textContent = txt; }
        }
        requestAnimationFrame(step);
      });
    } catch (e) { /* анимация не может ломать дашборд */ }
  }

  // Мягкое обновление KPI на дашборде — только числа, без перестройки DOM
  function softUpdateDashboard() {
    var vt = visibleTasks();
    var mastersToday = visibleMasters();
    var today = vt.filter(function (t) { return t.d === 0; });
    var overloads = mastersToday.filter(function (m) { return loadForDay(m.id, 0) > masterCapacity(m.id, 0); }).length;
    var permitCount = vt.filter(function(t) { return t.needs_permit && !isDone(t); }).length;

    // Обновляем только значения внутри существующих KPI карточек
    var kpiEls = document.querySelectorAll('.kpi .val');
    if (kpiEls.length >= 4) {
      if (kpiEls[0]) kpiEls[0].textContent = today.length;
      if (kpiEls[1]) kpiEls[1].textContent = overloads;
      // KPI 3 — процент выполнения
      var doneMonth = 0, totalMonth = 0;
      vt.forEach(function (t) {
        var d = offToDate(t.d);
        if (d.getMonth() === TODAY.getMonth() && d.getFullYear() === TODAY.getFullYear()) { totalMonth++; if (isDone(t)) doneMonth++; }
      });
      var pct = totalMonth ? Math.round(doneMonth / totalMonth * 100) : 0;
      if (kpiEls[2]) kpiEls[2].textContent = pct + '%';
      if (kpiEls[3]) kpiEls[3].textContent = permitCount;
    }
  }

  /* =====================================================================
     ПОПАП-КАЛЕНДАРЬ (выбор даты в планировании)
     ===================================================================== */
  var dpState = { viewMonth: new Date(TODAY.getFullYear(), TODAY.getMonth(), 1), selectedDate: null };

  function openDatePicker(anchorEl) {
    var popup = document.getElementById('date-popup');
    if (!popup) return;

    // Позиционируем попап относительно заголовка
    var rect = anchorEl.getBoundingClientRect();
    popup.style.left = Math.min(rect.left, window.innerWidth - 340) + 'px';
    popup.style.top = (rect.bottom + 8) + 'px';

    dpState.viewMonth = new Date(TODAY.getFullYear(), TODAY.getMonth(), 1);
    var shift = (S.calMode === 'week') ? S.weekShift : (S.calMode === 'month' ? S.monthShift : S.dayShift);
    if (S.calMode === 'week') dpState.viewMonth = addDays(mondayOf(TODAY), shift * 7);
    if (S.calMode === 'month') dpState.viewMonth = new Date(TODAY.getFullYear(), TODAY.getMonth() + shift, 1);
    if (S.calMode === 'day') dpState.viewMonth = addDays(TODAY, shift);

    renderDatePicker();
    popup.classList.add('open');

    // Закрытие по клику вне попапа
    setTimeout(function() {
      document.addEventListener('click', closeDatePickerOutside);
    }, 100);
  }

  function closeDatePickerOutside(e) {
    var popup = document.getElementById('date-popup');
    if (!popup || !popup.classList.contains('open')) return;
    if (!popup.contains(e.target) && !e.target.closest('#cal-title')) {
      closeDatePicker();
    }
  }

  function closeDatePicker() {
    var popup = document.getElementById('date-popup');
    if (popup) popup.classList.remove('open');
    document.removeEventListener('click', closeDatePickerOutside);
  }

  function renderDatePicker() {
    var m = dpState.viewMonth.getMonth();
    var y = dpState.viewMonth.getFullYear();
    var monthNames = ['Январь', 'Февраль', 'Март', 'Апрель', 'Май', 'Июнь', 'Июль', 'Август', 'Сентябрь', 'Октябрь', 'Ноябрь', 'Декабрь'];
    document.getElementById('dp-month-year').textContent = monthNames[m] + ' ' + y;

    var grid = document.getElementById('dp-grid');
    var html = '';
    var wds = ['Пн', 'Вт', 'Ср', 'Чт', 'Пт', 'Сб', 'Вс'];
    wds.forEach(function(wd) { html += '<div class="dp-wd">' + wd + '</div>'; });

    var firstDay = new Date(y, m, 1);
    var lastDay = new Date(y, m + 1, 0);
    var startOffset = (firstDay.getDay() + 6) % 7;

    // Дни предыдущего месяца
    for (var i = startOffset - 1; i >= 0; i--) {
      var d = new Date(y, m, -i);
      html += '<button class="dp-day other-month" data-date="' + key(d) + '">' + d.getDate() + '</button>';
    }

    // Текущий месяц
    for (var day = 1; day <= lastDay.getDate(); day++) {
      var d = new Date(y, m, day);
      var cls = 'dp-day';
      if (sameDay(d, TODAY)) cls += ' today';
      html += '<button class="' + cls + '" data-date="' + key(d) + '">' + day + '</button>';
    }

    // Дни следующего месяца
    var totalCells = startOffset + lastDay.getDate();
    var remaining = (7 - (totalCells % 7)) % 7;
    for (var j = 1; j <= remaining; j++) {
      var d = new Date(y, m + 1, j);
      html += '<button class="dp-day other-month" data-date="' + key(d) + '">' + j + '</button>';
    }

    grid.innerHTML = html;

    // Привязка кликов по дням
    grid.querySelectorAll('.dp-day').forEach(function(btn) {
      btn.addEventListener('click', function() {
        grid.querySelectorAll('.dp-day.selected').forEach(function(b) { b.classList.remove('selected'); });
        btn.classList.add('selected');
        dpState.selectedDate = btn.dataset.date;
      });
    });
  }

  function applyDatePicker() {
    if (!dpState.selectedDate) { closeDatePicker(); return; }
    var picked = new Date(dpState.selectedDate + 'T00:00:00');
    var off = dateToOff(picked);

    if (S.calMode === 'day') S.dayShift = off;
    else if (S.calMode === 'week') S.weekShift = Math.floor(off / 7);
    else if (S.calMode === 'month') S.monthShift = (picked.getFullYear() - TODAY.getFullYear()) * 12 + (picked.getMonth() - TODAY.getMonth());

    closeDatePicker();
    renderCalendar();
  }

  function initDatePicker() {
    var prev = document.getElementById('dp-prev');
    var next = document.getElementById('dp-next');
    var todayBtn = document.getElementById('dp-today');
    var cancelBtn = document.getElementById('dp-cancel');
    var applyBtn = document.getElementById('dp-apply');

    if (prev) prev.addEventListener('click', function() {
      dpState.viewMonth = new Date(dpState.viewMonth.getFullYear(), dpState.viewMonth.getMonth() - 1, 1);
      renderDatePicker();
    });
    if (next) next.addEventListener('click', function() {
      dpState.viewMonth = new Date(dpState.viewMonth.getFullYear(), dpState.viewMonth.getMonth() + 1, 1);
      renderDatePicker();
    });
    if (todayBtn) todayBtn.addEventListener('click', function() {
      dpState.viewMonth = new Date(TODAY.getFullYear(), TODAY.getMonth(), 1);
      renderDatePicker();
    });
    if (cancelBtn) cancelBtn.addEventListener('click', closeDatePicker);
    if (applyBtn) applyBtn.addEventListener('click', applyDatePicker);
  }

  /* =====================================================================
     КОРЗИНА (синхронизированная через сервер)
     ===================================================================== */
  var TRASH_KEY = 'smartplan_trash';

  function getTrash() {
    try { var raw = localStorage.getItem(TRASH_KEY); if (raw) return JSON.parse(raw); } catch (e) {}
    return [];
  }

  function saveTrash(arr) {
    try { localStorage.setItem(TRASH_KEY, JSON.stringify(arr)); } catch (e) {}
  }

  // Загрузка корзины с сервера
  function loadTrashFromServer() {
    var API = (window.SP_CONFIG && SP_CONFIG.serverUrl) || '';
    if (!API || !DB.isServerOnline()) return Promise.resolve(getTrash());
    return fetch(API + '/api/trash')
      .then(function(r) { return r.json(); })
      .then(function(data) {
        if (data && data.tasks) {
          var trash = data.tasks.map(function(t) {
            return Object.assign({}, t, { _deletedAt: t.created || Date.now() });
          });
          saveTrash(trash);
          return trash;
        }
        return getTrash();
      })
      .catch(function() { return getTrash(); });
  }

  function addToTrash(task) {
    var trash = getTrash();
    task._deletedAt = Date.now();
    trash.push(task);
    // Оставляем только задачи за последние 14 дней
    var cutoff = Date.now() - 14 * 86400000;
    trash = trash.filter(function(t) { return t._deletedAt > cutoff; });
    saveTrash(trash);
    // Отправляем на сервер — мягкое удаление
    var API = (window.SP_CONFIG && SP_CONFIG.serverUrl) || '';
    if (API && DB.isServerOnline()) {
      fetch(API + '/api/tasks/' + task.id, { method: 'DELETE' }).catch(function() {});
    }
  }

  function restoreFromTrash(trashIdx) {
    var trash = getTrash();
    if (trashIdx < 0 || trashIdx >= trash.length) return;
    var task = trash[trashIdx];
    trash.splice(trashIdx, 1);
    saveTrash(trash);

    var API = (window.SP_CONFIG && SP_CONFIG.serverUrl) || '';

    // Сначала восстанавливаем на сервере, потом обновляем всё
    var restorePromise;
    if (API && DB.isServerOnline()) {
      restorePromise = fetch(API + '/api/trash/restore/' + task.id, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ status: 'plan', s: 'plan', addr: task.addr || '', m: task.m || '', d: task.d || 0, dl: task.dl || 7, volume: task.volume || 1 })
      }).catch(function() {});
    } else {
      // Автономный режим — добавляем локально
      task.s = 'plan'; task.status = 'plan';
      delete task._deletedAt;
      if (TASKS_DB) { TASKS_DB.addTask(task); S.tasks = TASKS_DB.getTasks(); }
      restorePromise = Promise.resolve();
    }

    restorePromise.then(function() {
      // Полное обновление данных с сервера
      if (DB.isServerOnline()) {
        DB.syncFromServer().then(function() {
          if (window.SP_TASKS) S.tasks = window.SP_TASKS.getTasks();
          drawCalendarGrid();
          openTrashModal();
        });
      } else {
        drawCalendarGrid();
        openTrashModal();
      }
    });
    toast('ok', '✅ Задача восстановлена из корзины');
  }

  function purgeTrash() {
    var oldTrash = getTrash();
    saveTrash([]);
    var API = (window.SP_CONFIG && SP_CONFIG.serverUrl) || '';
    var purgePromises = [];
    if (API && DB.isServerOnline()) {
      oldTrash.forEach(function(t) {
        if (t.id) {
          purgePromises.push(fetch(API + '/api/trash/' + t.id, { method: 'DELETE' }).catch(function() {}));
        }
      });
    }
    // Ждём удаления с сервера, потом обновляем всё
    Promise.all(purgePromises).then(function() {
      if (DB.isServerOnline()) {
        DB.syncFromServer().then(function() {
          if (window.SP_TASKS) S.tasks = window.SP_TASKS.getTasks();
          drawCalendarGrid();
          openTrashModal();
        });
      } else {
        drawCalendarGrid();
        openTrashModal();
      }
    });
    toast('ok', '🗑 Корзина очищена');
  }

  function openTrashModal() {
    // Показываем загрузку
    modal.style.maxWidth = ''; // сброс автоширины карточки задачи
    modal.innerHTML = '<div class="modal-h"><h3>🗑 Корзина</h3><button class="x" data-action="close-modal">×</button></div><div class="modal-b"><div class="empty" style="padding:40px 20px;">Загрузка...</div></div>';
    overlay.classList.add('show');

    // Загружаем актуальную корзину с сервера
    loadTrashFromServer().then(function(trash) {
      trash.sort(function(a, b) { return (b._deletedAt || 0) - (a._deletedAt || 0); });
      var html = '<div class="modal-h"><h3>🗑 Корзина</h3><button class="x" data-action="close-modal">×</button></div>';
      html += '<div class="modal-b">';
      if (!trash.length) {
        html += '<div class="empty" style="padding:40px 20px;">Корзина пуста<br><span style="font-size:12px;">Удалённые задачи хранятся 14 дней</span></div>';
      } else {
        html += '<div style="font-size:12px;color:var(--muted);margin-bottom:12px;">Задач в корзине: ' + trash.length + ' · хранятся 14 дней · синхронизировано</div>';
        trash.forEach(function(t, idx) {
          var w = WORK.getWork('УБиРОГС', t.w) || WORK_MAP[t.w];
          var deletedDate = parseLogDate(t._deletedAt);
          var delStr = deletedDate ? deletedDate.getDate() + ' ' + MON[deletedDate.getMonth()] : '—';
          var daysAgo = deletedDate ? Math.floor((Date.now() - deletedDate.getTime()) / 86400000) : -1;
          html += '<div class="rz-item"><div class="rz-bar" style="background:var(--muted);"></div><div class="rz-main"><div class="rz-t">' + esc(w ? w.name : 'Задача') + ' — ' + esc(t.addr || addrOf(t)) + '</div><div class="rz-s">Удалено: ' + delStr + ' · ' + (daysAgo < 0 ? 'недавно' : daysAgo === 0 ? 'сегодня' : daysAgo + ' дн назад') + ' · Объём: ' + (t.volume || 1) + '</div></div>' + (canPlan() ? '<button class="btn sm" data-action="restore-task" data-trash-idx="' + idx + '" style="color:var(--green);white-space:nowrap;">↩ Восстановить</button>' : '<span style="font-size:11px;color:var(--muted)">только просмотр</span>') + '</div>';
        });
        if (canPlan()) html += '<div style="margin-top:16px;text-align:right;"><button class="btn sm" data-action="purge-trash" style="color:var(--red);">Очистить корзину полностью</button></div>';
      }
      html += '</div><div class="modal-f"><button class="btn" data-action="close-modal">Закрыть</button></div>';
      modal.innerHTML = html;
    });
  }

  /* =====================================================================
     РЕНДЕР: КАЛЕНДАРЬ
     ===================================================================== */
  function renderCalendar() {
    var html = '<div class="cal-head"><div class="seg">';
    html += segBtn('day', 'День') + segBtn('week', 'Неделя') + segBtn('month', 'Месяц');
    html += '</div>';
    html += '<button class="btn sm" data-action="cal-prev">‹</button>';
    html += '<span class="cal-title" id="cal-title" style="cursor:pointer;padding:4px 12px;border-radius:8px;transition:.15s;text-decoration:underline;text-decoration-color:transparent;text-underline-offset:3px;" onmouseover="this.style.background=\'#eff6ff\';this.style.textDecorationColor=\'#2563eb\'" onmouseout="this.style.background=\'transparent\';this.style.textDecorationColor=\'transparent\'" title="Нажмите для выбора даты"></span>';
    html += '<button class="btn sm" data-action="cal-next">›</button>';
    if (S.calMode !== 'day' || S.dayShift !== 0) html += '<button class="btn sm" data-action="cal-today">Сегодня</button>';
    if (canPlan()) {
      html += '<button class="btn sm primary" data-action="new-task">' + IC.plus + ' Добавить задачу</button>';
      html += '<button class="btn sm" data-action="optimize-works" style="background:#6366f1;color:#fff;border-color:#6366f1;" title="Автоматическое распределение работ без просрочек с соблюдением 8-часового рабочего дня">⚡ Оптимизировать работы</button>';
    }
    html += '<div class="trash-zone" id="trash-zone" data-action="open-trash" title="Перетащите задачу для удаления или нажмите для просмотра удалённых" style="cursor:pointer;">' + IC.trash + ' <span>Корзина</span></div>';
    html += '<div class="legend"><span><i style="background:var(--green-l);border:1px solid var(--green)"></i>В норме</span><span><i style="background:var(--yellow-l);border:1px solid var(--yellow)"></i>Мало времени</span><span><i style="background:var(--red-l);border:1px solid var(--red)"></i>Просрочка</span><span><i style="background:#fef3c7;border:1px solid #f59e0b"></i>Ожидание погоды</span><span><i style="background:var(--panel-3);border:1px solid #94a3b8"></i>Выполнено</span></div>';
    html += '</div>';
    if (S.role === 'master') {
      html += '<div class="calc" style="margin-bottom:12px"><span style="text-align:left">' + IC.info + ' Ваш личный график. Перетаскивайте карточки, чтобы менять дату выполнения.</span></div>';
    } else if (S.role !== 'admin') {
      html += '<div class="calc" style="margin-bottom:12px"><span style="text-align:left">' + IC.info + ' Участок <b>' + esc(S.user.area) + '</b>: доступны только мастера этого участка.</span></div>';
    }
    html += '<div class="cal-scroll"><div class="cal-grid ' + S.calMode + '" id="cal-grid"></div></div>';
    view.innerHTML = html;
    drawCalendarGrid();
  }
  function segBtn(mode, label) {
    return '<button class="' + (S.calMode === mode ? 'on' : '') + '" data-action="cal-mode" data-mode="' + mode + '">' + label + '</button>';
  }
  var _drawGridTm = null;
  function drawCalendarGrid() {
    if (_drawGridTm) clearTimeout(_drawGridTm);
    _drawGridTm = setTimeout(_drawCalendarGridImpl, 50);
  }
  function _drawCalendarGridImpl() {
    var grid = document.getElementById('cal-grid');
    // 22.09-198: в «Планировании» строки — ТОЛЬКО у мастеров (начальник участка и старший мастер строк не имеют)
    var masters = visibleMasters().filter(function (m) { return m.role === 'master'; });
    var days = buildDayWindow();
    var titleEl = document.getElementById('cal-title');
    if (titleEl) {
      titleEl.textContent = windowTitle(days);
      // Привязка открытия календаря
      titleEl.onclick = function() { openDatePicker(titleEl); };
    }

    if (!masters.length) {
      grid.style.gridTemplateColumns = '1fr';
      grid.innerHTML = '<div style="padding:44px 20px;text-align:center;color:var(--muted)"><div style="font-size:38px;margin-bottom:12px">👥</div><div style="color:var(--ink);font-size:15px;font-weight:700">Нет мастеров для планирования</div><div style="margin-top:8px;font-size:12.5px;max-width:420px;margin-left:auto;margin-right:auto">Добавьте пользователей с ролью «Мастер» или «Старший мастер» в разделе «Пользователи» — они автоматически появятся здесь как строки календаря.</div></div>';
      return;
    }

    // Ширина ячейки с задачей одинаковая в неделе и месяце:
    // стандарт — ячейка недели = (ширина контейнера − колонка мастеров) / 7.
    // Режим «День» — как раньше: единственная колонка на всю ширину.
    grid.style.gridTemplateColumns = '170px repeat(' + days.length + ', ' + (S.calMode === 'day' ? '1fr' : 'calc((100% - 170px) / 7)') + ')';
    var html = '';
    html += '<div class="col-head gh corner" style="grid-column:1;grid-row:1">Мастер / Бригада</div>';
    days.forEach(function (d, i) {
      var we = (d.getDay() === 0 || d.getDay() === 6);
      var cls = 'col-head gh' + (sameDay(d, TODAY) ? ' today' : '') + (we ? ' we' : '');
      html += '<div class="' + cls + '" style="grid-column:' + (i + 2) + ';grid-row:1"><div class="dn">' + d.getDate() + '</div><div class="wd">' + WD[d.getDay()] + '</div></div>';
    });
    masters.forEach(function (m, ri) {
      var rn = ri + 2;
      // Состояние смены «на сегодня» — цветной текст под участком (данные из workers_db).
      var _tSt = wkDayState(m.id, key(TODAY));
      var _tStClr = _tSt === 'work' ? '#16a34a' : (_tSt === 'abs' ? '#dc2626' : '#94a3b8');
      var _tStIco = _tSt === 'work' ? '●' : (_tSt === 'abs' ? '⛔' : '○');
      var _tStLbl = _tSt === 'work' ? 'сегодня — рабочий' : (_tSt === 'abs' ? 'сегодня — отсутствие' : 'сегодня — выходной');
      html += '<div class="mname" data-action="master-sch-popup" data-uid="' + esc(m.id) + '" title="Открыть график смен — ' + esc(m.name) + '" style="grid-column:1;grid-row:' + rn + ';cursor:pointer"><span class="dot" style="background:' + m.color + '"></span><div><div class="nm">' + esc(m.name) + '</div><div class="ar">' + esc(m.area) + '</div><div class="sh-today" style="font-size:9.5px;font-weight:800;color:' + _tStClr + ';margin-top:1px;line-height:1.2">' + _tStIco + ' ' + _tStLbl + '</div></div></div>';
      days.forEach(function (d, ci) {
        var off = dateToOff(d);
        var acKey = m.id + '_' + off;
        // Фоновый расчёт маршрута для ячейки — запускаем ДО отрисовки,
        // чтобы успеть выставить статус 'loading' и показать «🚗 расчёт…»
        var dayTasks = S.tasks.filter(function(t) { return t.m === m.id && t.d === off && !isDone(t); });
        if (dayTasks.length >= 1 && !autoRouteCache[acKey]) autoCalcRoute(m.id, off, dayTasks);
        var _cellRT = getRouteTime(m.id, off);
        var _cellAC = autoRouteCache[acKey];
        var cellLegs = (_cellAC && _cellAC.legs) ? _cellAC.legs : (_cellRT && _cellRT.legs ? _cellRT.legs : null);
        var load = loadForDay(m.id, off);
        var over = load > masterCapacity(m.id, off);
        var we = (d.getDay() === 0 || d.getDay() === 6);
        var cls = 'cell' + (sameDay(d, TODAY) ? ' today' : '') + (we ? ' we' : '') + (over ? ' overload' : ''); // 22.09-104: подсветка рабочих дней убрана
        html += '<div class="' + cls + '" style="grid-column:' + (ci + 2) + ';grid-row:' + rn + '" data-master="' + m.id + '" data-off="' + off + '"' + (over ? ' title="Перегрузка: ' + fmtH(load) + ' ч"' : '') + '>';
        S.tasks.filter(function (t) { return t.m === m.id && t.d === off; }).sort(dayTaskSort).forEach(function (t) { // 22.09-197: порядок — как после оптимизации маршрута (t.seq)
          {
            var col = taskColor(t);
            var o = OBJ_MAP[t.o], w = workOf(t);
            var draggable = (!isDone(t) && canEditTask(t)) ? 'true' : 'false';
            var wMeta = workOf(t);
            var badges = '';
            var permitLine = '';
            if (t.needs_permit) {
              permitLine = '<span class="tile-permit">📋 Ордер до: ' + (t.dl_date || '—') + '</span>';
            } else if (wMeta && wMeta.min_temp > -50) {
              var wf = getWeatherForecast(off);
              if (wf && wf.temp != null && wf.temp < wMeta.min_temp) badges += '<span class="ov-weather">⚠</span>';
            }
            var legInfo = cellLegs ? cellLegs[t.id] : null;
            if (!legInfo && t.travelMin != null && t.travelKm != null) legInfo = { min: t.travelMin, km: t.travelKm };
            // Есть ли координаты у задачи (иначе адрес не найден картой)
            var _hasCoords = (t.lat != null && t.lng != null);
            if (!_hasCoords && t.o) { var _o = OBJ_MAP[t.o]; if (_o && _o.lat && _o.lng) _hasCoords = true; }
            if (!_hasCoords && t.addr) { var _gc = getTaskCoords(t.addr); if (_gc) _hasCoords = true; }
            var tileLegHtml;
            if (legInfo) {
              tileLegHtml = '<span class="tile-leg" style="display:block;font-size:10px;color:#2563eb;font-weight:600;margin-top:2px;white-space:nowrap;">🚗 ' + fmtDuration(legInfo.min) + ' · ' + (legInfo.km || 0).toFixed(1).replace('.', ',') + ' км</span>';
            } else if (!_hasCoords) {
              tileLegHtml = '<span class="tile-leg" style="display:block;font-size:10px;color:#dc2626;font-weight:600;margin-top:2px;white-space:nowrap;">⚠ Адрес не найден</span>';
            } else {
              tileLegHtml = '';
            }
            html += '<div class="tile t-' + col + '" draggable="' + draggable + '" data-action="edit-task" data-tid="' + t.id + '" title="Нажмите для редактирования задания">' + badges + '<span class="tw">' + esc(w ? w.name : '?') + ((t.volume || t.volumes) ? ' ×' + taskVolLabel(t) : '') + (t.brigade ? ' 🔧бриг.' : (t.slesari && t.slesari.length ? ' 🔧' + t.slesari.length : '')) + '</span><span class="th">' + esc(addrOf(t)) + ' · ' + fmtH(taskHours(t)) + 'ч</span>' + permitLine + tileLegHtml + '<label class="tile-chk" onmousedown="event.stopPropagation()" ondragstart="return false"><input type="checkbox" data-action="toggle-done" data-tid="' + t.id + '"' + (isDone(t) ? ' checked' : '') + (S.role === 'viewer' ? ' disabled' : '') + '><span class="tile-chk-box"></span></label></div>';
          }
        });
        // Время до объекта — только ВНУТРИ плашки задачи (tile-leg);
        // отдельной строки «🚗 время в пути» под плашками больше нет
        html += '</div>';
      });
    });
    grid.innerHTML = html;
    attachCalDnD();
  }
  function buildDayWindow() {
    var arr = [];
    if (S.calMode === 'week') {
      var start = addDays(mondayOf(TODAY), S.weekShift * 7);
      for (var i = 0; i < 7; i++) arr.push(addDays(start, i));
    } else if (S.calMode === 'day') {
      arr.push(addDays(TODAY, S.dayShift));
    } else {
      var base = new Date(TODAY.getFullYear(), TODAY.getMonth() + S.monthShift, 1);
      var n = new Date(base.getFullYear(), base.getMonth() + 1, 0).getDate();
      for (var j = 1; j <= n; j++) arr.push(new Date(base.getFullYear(), base.getMonth(), j));
    }
    return arr;
  }
  function windowTitle(days) {
    if (S.calMode === 'day') return fmt(days[0]) + ' · ' + WD_FULL[days[0].getDay()];
    if (S.calMode === 'week') return fmt(days[0]) + ' — ' + fmt(days[6]);
    return MON_NOM[days[0].getMonth()] + ' ' + days[0].getFullYear();
  }

  /* =====================================================================
     БЫСТРОЕ ОКНО ГРАФИКА РАБОТНИКА (из «Планирование / Календарь»)
     Поверх текущего экрана показывает месячную сетку со сменами из
     workers_db: работает / выходной / отсутствие. Односторонняя связь —
     задачи графика работ сюда не подтягиваются.
     ===================================================================== */
  function openMasterSchPopup(uid, baseDate) {
    var u = DB.getUser(uid);
    if (!u) return;
    var wkd = wkData(uid);
    var base = baseDate || TODAY;
    var pY = base.getFullYear(), pM = base.getMonth();
    var dim = new Date(pY, pM + 1, 0).getDate();
    var lead = (new Date(pY, pM, 1).getDay() + 6) % 7; // Пн=0 … Вс=6
    var stWork = 0, stOff = 0, stAbs = 0;
    var cells = '';
    for (var li = 0; li < lead; li++) cells += '<div style="min-height:46px"></div>';
    for (var dd = 1; dd <= dim; dd++) {
      var dt = new Date(pY, pM, dd);
      var ds = key(dt);
      var st = wkDayState(uid, ds);
      if (st === 'work') stWork++; else if (st === 'abs') stAbs++; else stOff++;
      var bg2 = st === 'work' ? '#dcfce7' : (st === 'abs' ? '#fee2e2' : '#f1f5f9');
      var bd2 = st === 'work' ? '#16a34a' : (st === 'abs' ? '#dc2626' : '#cbd5e1');
      var isT = sameDay(dt, TODAY);
      var tip = ds + (st === 'work' ? ' · рабочий' : (st === 'abs' ? ' · отсутствие' + (wkd.abs[ds] ? ' (' + esc(wkd.abs[ds]) + ')' : '') : ' · выходной'));
      cells += '<div title="' + esc(tip) + '" style="min-height:46px;border-radius:8px;background:' + bg2 + ';border:1px solid ' + bd2 + ';display:flex;flex-direction:column;align-items:center;justify-content:center;font-size:12px;font-weight:800;color:var(--ink);padding:2px' + (isT ? ';box-shadow:inset 0 0 0 2px rgba(37,99,235,.55)' : '') + '">' + dd + '<span style="font-size:9.5px;font-weight:700;color:var(--muted);line-height:1.1">' + WD[dt.getDay()] + '</span></div>';
    }
    var roles = ROLE_INFO[u.role] ? ROLE_INFO[u.role].label : (u.role || '');
    var h = '<div class="modal-h"><h3>📅 ' + esc(u.full_name) + ' — ' + MON_NOM[pM] + ' ' + pY + '</h3><button class="x" data-action="close-modal">×</button></div>';
    h += '<div class="modal-b">';
    h += '<div style="display:flex;gap:7px;flex-wrap:wrap;align-items:center;margin-bottom:12px;font-size:12px;color:var(--muted)">' +
      '<span class="chip" style="background:#eff6ff;color:#1d4ed8">' + wkd.hours + ' ч</span>' +
      '<span class="chip" style="background:#f0fdf4;color:#15803d">' + esc(wkd.sched) + '</span>' +
      (wkd.sched === '2/2' ? '<span class="chip" style="background:#fef9c3;color:#854d0e">цикл с ' + esc(wkd.cycle) + '</span>' : '') +
      (roles ? '<span class="chip" style="background:#f3f4f6;color:#374151">' + esc(roles) + '</span>' : '') +
      '<span style="flex:1"></span>' +
      '<span style="font-weight:700;white-space:nowrap"><span style="color:#16a34a">' + stWork + ' раб</span> · <span style="color:#94a3b8">' + stOff + ' вых</span> · <span style="color:#dc2626">' + stAbs + ' отс</span></span>' +
      '</div>';
    h += '<div style="display:grid;grid-template-columns:repeat(7,1fr);gap:5px;margin-bottom:6px">' +
      ['Пн', 'Вт', 'Ср', 'Чт', 'Пт', 'Сб', 'Вс'].map(function (wdName, i) {
        return '<div style="text-align:center;font-size:11px;font-weight:800;color:' + (i >= 5 ? '#94a3b8' : 'var(--muted)') + '">' + wdName + '</div>';
      }).join('') + '</div>';
    h += '<div style="display:grid;grid-template-columns:repeat(7,1fr);gap:5px">' + cells + '</div>';
    h += '<div style="margin-top:14px;display:flex;gap:14px;align-items:center;font-size:11px;color:var(--muted);flex-wrap:wrap;font-weight:700">' +
      '<span style="display:inline-flex;gap:5px;align-items:center"><span style="width:14px;height:14px;border-radius:3px;background:#dcfce7;border:1px solid #16a34a"></span>рабочий</span>' +
      '<span style="display:inline-flex;gap:5px;align-items:center"><span style="width:14px;height:14px;border-radius:3px;background:#f1f5f9;border:1px solid #cbd5e1"></span>выходной</span>' +
      '<span style="display:inline-flex;gap:5px;align-items:center"><span style="width:14px;height:14px;border-radius:3px;background:#fee2e2;border:1px solid #dc2626"></span>отсутствие</span>' +
      '<span style="color:#94a3b8">· нажмите на имя мастера в календаре, чтобы открыть это окно</span>' +
      '</div>';
    h += '</div>';
    h += '<div class="modal-f">' +
      '<button type="button" class="btn" data-action="master-sch-goto" data-uid="' + esc(uid) + '" title="Перейти к полной таблице в разделе «Графики смен»">↗ В «Графики смен»</button>' +
      '<button type="button" class="btn danger" data-action="close-modal">Закрыть</button>' +
      '</div>';
    modal.innerHTML = h;
    modal.style.maxWidth = '560px';
    overlay.classList.add('show');
  }

  /* ---------- DRAG & DROP ---------- */
  var dragId = null;
  /* === Общие функции переноса задач (используются DnD и touch) === */
  function moveTaskToCell(id, cell) {
    var t = findTask(id); if (!t) return;
    if (!canEditTask(t)) { toast('err', 'Нет прав на редактирование этой задачи'); return; }
    var newMaster = cell.dataset.master, newOff = parseInt(cell.dataset.off, 10);
    var oldM = t.m, oldOff = t.d;
    if (!canDropOn(newMaster)) { toast('err', 'Этот мастер вне вашего доступа'); return; }
    var target = masterById(newMaster);
    // 22.09-80: мастер в этот день не работает (график смен) — НЕ запрещаем
    // (бывают аварийные вызовы), но предупреждаем после переноса.
    var _wkOffWarn = wkOffDayWarn(newMaster, newOff);
    var moved = [];
    if (t.m !== newMaster) { t.m = newMaster; moved.push('мастер → ' + (target ? target.name : '?')); }
    if (t.d !== newOff) { t.d = newOff; moved.push('дата → ' + fmtShort(newOff)); }
    if (moved.length) {
      if (TASKS_DB) { TASKS_DB.updateTask(t.id, t); }
      // Задача из графика: перемещение сдвигает её в графике и все последующие
      // вхождения серии — соответственно периодичности
      if (t.graphId) { try { graphSeriesOnMove(t); } catch (e) {} }
      invalidateRouteCache(oldM, oldOff);
      invalidateRouteCache(newMaster, newOff);
      logAction('Перемещение задачи', (target ? target.name : '?') + ': ' + moved.join(', '));
      drawCalendarGrid();
      if (_wkOffWarn) toast('warn', _wkOffWarn);
      var load = loadForDay(newMaster, newOff);
      if (_wkOffWarn) { /* день нерабочий — перегрузочный тост не дублируем */ }
      else if (load > masterCapacity(newMaster, newOff)) {
        toast('warn', '🛑 Аналитика помощника : Внимание! Перегрузка мастера ' + (target ? target.name : '') + ' до ' + fmtH(load) + ' ч (при норме ' + fmtH(masterCapacity(newMaster, newOff)) + ' ч). Предлагаем перенести задачу на другой день или заменить мастера!');
      } else {
        toast('ok', '💡 Аналитика помощника : Перенос успешно выполнен. Текущая загрузка мастера ' + (target ? target.name : '') + ' на этот день составляет ' + fmtH(load) + ' ч / ' + fmtH(masterCapacity(newMaster, newOff)) + ' ч.');
      }
    }
  }

  function deleteTaskToTrash(id) {
    var t = findTask(id); if (!t) return;
    if (!canEditTask(t)) { toast('err', 'Нет прав на удаление этой задачи'); return; }
    var w = workOf(t);
    if (!window.confirm('Удалить задачу «' + (w ? w.name : '?') + ' — ' + addrOf(t) + '»?')) return;
    addToTrash(JSON.parse(JSON.stringify(t)));
    if (TASKS_DB) { TASKS_DB.deleteTask(id); S.tasks = TASKS_DB.getTasks(); } else { S.tasks = S.tasks.filter(function (x) { return x.id !== id; }); }
    invalidateRouteCache(t.m, t.d);
    drawCalendarGrid();
    logAction('Удаление задачи', (w ? w.name : '?') + ' — ' + addrOf(t));
        toast('ok', '🗑️ Аналитика помощника : Задача удалена. Освободилось ' + fmtH(taskHours(t)) + ' ч у мастера ' + (masterById(t.m) ? masterById(t.m).name : '?') + '.');
  }

  function reorderMapCard(fromId, toId) {
    var pts = ymState.pts;
    if (!pts || !pts.length) return;
    var fromIdx = -1, toIdx = -1;
    pts.forEach(function (p, i) {
      if (p.id === fromId) fromIdx = i;
      if (p.id === toId) toIdx = i;
    });
    if (fromIdx === -1 || toIdx === -1 || fromIdx === toIdx) return;
    var moved = pts.splice(fromIdx, 1)[0];
    pts.splice(toIdx, 0, moved);
    ymState.manualOrder = true;
    refreshMapCards(pts);
    drawMap(pts);
    toast('ok', 'Порядок изменён');
  }

  /* === Touch Drag & Drop Polyfill (для планшетов и телефонов) === */
  function enableTouchDnD() {
    var ts = null; // touchState

    function onStart(e) {
      var tile = e.target.closest('.tile[draggable="true"]');
      var mtask = e.target.closest('.mtask[draggable="true"]');
      var wkcard = e.target.closest('.wk-card[draggable="true"]'); // карточка слесаря (страница «Работники»)
      var el = tile || mtask || wkcard;
      if (!el) return;
      // Не мешаем кликам по чекбоксам, кнопкам и grip-иконкам
      if (e.target.closest('.tile-chk') || e.target.closest('button') || e.target.tagName === 'INPUT') return;
      var touch = e.touches[0];
      ts = {
        type: tile ? 'tile' : (mtask ? 'mtask' : 'wkcard'),
        id: tile ? tile.dataset.tid : (mtask ? mtask.dataset.mid : wkcard.dataset.uid),
        startX: touch.clientX, startY: touch.clientY,
        moved: false, el: el, ghost: null, dropTarget: null, dropType: null
      };
    }

    function onMove(e) {
      if (!ts) return;
      var touch = e.touches[0];
      if (!ts.moved) {
        if (Math.abs(touch.clientX - ts.startX) < 8 && Math.abs(touch.clientY - ts.startY) < 8) return;
        ts.moved = true;
        // Создаём ghost-клон
        var rect = ts.el.getBoundingClientRect();
        ts.ghost = ts.el.cloneNode(true);
        ts.ghost.style.cssText = 'position:fixed;z-index:99999;opacity:0.85;pointer-events:none;width:' + rect.width + 'px;transform:scale(0.92) rotate(-1deg);box-shadow:0 8px 24px rgba(0,0,0,.3);';
        document.body.appendChild(ts.ghost);
        ts.el.style.opacity = '0.25';
      }
      if (ts.moved) {
        e.preventDefault();
        var g = ts.ghost;
        g.style.left = (touch.clientX - g.offsetWidth / 2) + 'px';
        g.style.top = (touch.clientY - 25) + 'px';
        // Найти элемент под пальцем (скрываем ghost на мгновение)
        g.style.display = 'none';
        var under = document.elementFromPoint(touch.clientX, touch.clientY);
        g.style.display = '';

        // Очистка старой подсветки
        document.querySelectorAll('.cell.drop-on').forEach(function (c) { c.classList.remove('drop-on'); });
        document.querySelectorAll('.mtask.drop-above').forEach(function (c) { c.classList.remove('drop-above'); });
        document.querySelectorAll('.wk-drop-on').forEach(function (c) { c.classList.remove('wk-drop-on'); });
        var tr = document.getElementById('trash-zone');
        if (tr) tr.classList.remove('drop-active');

        ts.dropType = null; ts.dropTarget = null;

        if (ts.type === 'wkcard') {
          var wkzone = under ? under.closest('[data-wk-drop]') : null;
          if (wkzone) { wkzone.classList.add('wk-drop-on'); ts.dropType = 'wkzone'; ts.dropTarget = wkzone; }
        } else if (ts.type === 'tile') {
          var cell = under ? under.closest('.cell') : null;
          var trash = under ? under.closest('.trash-zone') : null;
          if (cell) { cell.classList.add('drop-on'); ts.dropType = 'cell'; ts.dropTarget = cell; }
          else if (trash) { trash.classList.add('drop-active'); ts.dropType = 'trash'; ts.dropTarget = trash; }
        } else if (ts.type === 'mtask') {
          var card = under ? under.closest('.mtask') : null;
          if (card && card.dataset.mid !== ts.id) { card.classList.add('drop-above'); ts.dropType = 'mtask'; ts.dropTarget = card; }
        }
      }
    }

    function onEnd(e) {
      if (!ts) return;
      if (ts.ghost) ts.ghost.remove();
      if (ts.el) ts.el.style.opacity = '';
      document.querySelectorAll('.cell.drop-on').forEach(function (c) { c.classList.remove('drop-on'); });
      document.querySelectorAll('.mtask.drop-above').forEach(function (c) { c.classList.remove('drop-above'); });
      document.querySelectorAll('.wk-drop-on').forEach(function (c) { c.classList.remove('wk-drop-on'); });
      var tr = document.getElementById('trash-zone');
      if (tr) tr.classList.remove('drop-active');

      if (ts.moved && ts.dropType && ts.dropTarget) {
        if (ts.dropType === 'cell') moveTaskToCell(ts.id, ts.dropTarget);
        else if (ts.dropType === 'trash') deleteTaskToTrash(ts.id);
        else if (ts.dropType === 'mtask') reorderMapCard(ts.id, ts.dropTarget.dataset.mid);
        else if (ts.dropType === 'wkzone') wkDropSlesar(ts.id, ts.dropTarget.getAttribute('data-wk-drop') || '');
      }
      ts = null;
    }

    document.addEventListener('touchstart', onStart, { passive: true });
    document.addEventListener('touchmove', onMove, { passive: false });
    document.addEventListener('touchend', onEnd, { passive: true });
    document.addEventListener('touchcancel', onEnd, { passive: true });
  }

  function attachCalDnD() {
    var grid = document.getElementById('cal-grid'); if (!grid) return;
    grid.addEventListener('dragstart', function (e) {
      var tile = e.target.closest('.tile'); if (!tile) return;
      dragId = tile.dataset.tid; tile.classList.add('dragging');
      e.dataTransfer.effectAllowed = 'move';
      try { e.dataTransfer.setData('text/plain', dragId); } catch (err) {}
    });
    grid.addEventListener('dragend', function () {
      document.querySelectorAll('.tile.dragging').forEach(function (t) { t.classList.remove('dragging'); });
      document.querySelectorAll('.cell.drop-on').forEach(function (c) { c.classList.remove('drop-on'); });
      dragId = null;
    });
    grid.addEventListener('dragover', function (e) {
      if (!dragId) return;
      var cell = e.target.closest('.cell'); if (!cell) return;
      e.preventDefault(); e.dataTransfer.dropEffect = 'move';
      document.querySelectorAll('.cell.drop-on').forEach(function (c) { if (c !== cell) c.classList.remove('drop-on'); });
      cell.classList.add('drop-on');
    });
    grid.addEventListener('drop', function (e) {
      if (!dragId) return;
      var cell = e.target.closest('.cell'); if (!cell) return;
      e.preventDefault();
      cell.classList.remove('drop-on');
      var id = dragId || (e.dataTransfer && e.dataTransfer.getData('text/plain'));
      moveTaskToCell(id, cell);
    });
    grid.addEventListener('mousemove', tipHandler);
    grid.addEventListener('mouseleave', function () { tip.style.display = 'none'; });

    // === КОРЗИНА: перетаскивание задачи для удаления ===
    var trash = document.getElementById('trash-zone');
    if (trash) {
      trash.addEventListener('dragover', function (e) {
        if (!dragId) return;
        e.preventDefault();
        e.dataTransfer.dropEffect = 'move';
        trash.classList.add('drop-active');
      });
      trash.addEventListener('dragleave', function () { trash.classList.remove('drop-active'); });
      trash.addEventListener('drop', function (e) {
        e.preventDefault();
        trash.classList.remove('drop-active');
        if (!dragId) return;
        deleteTaskToTrash(dragId);
      });
    }
  }
  function tipHandler(e) {
    var tile = e.target.closest('.tile');
    if (!tile) { tip.style.display = 'none'; return; }
    var t = findTask(tile.dataset.tid); if (!t) return;
    var o = OBJ_MAP[t.o], w = workOf(t), m = masterById(t.m);
    var dlTxt = t.dl < 0 ? '<b style="color:#fca5a5">просрочка ' + (-t.dl) + ' дн</b>' : t.dl === 0 ? '<b style="color:#fde047">дедлайн сегодня</b>' : 'дедлайн: ' + fmtShort(t.dl);
    tip.innerHTML = '<b>' + esc(w ? w.name : '?') + '</b><br>' + esc(addrOf(t)) + ' · ' + esc(o ? o.type : '') + '<br>Объём: ' + (t.volume || 1) + ' ' + (w ? w.unit : '') + ' — ' + fmtH(taskHours(t)) + ' ч' +
      (t.needs_permit ? '<br><b style="color:#fca5a5">📋 Ордер до: ' + (t.dl_date || '—') + '</b>' : '') +
      (t.depends_on_snow ? '<br><b style="color:#7dd3fc">❄️ Снегозависимая (норматив 48 ч)</b>' : '') +
      (w && w.min_temp > -50 ? '<br><b style="color:#fbbf24">🌡️ Мин. t: +' + w.min_temp + '°C' + (function(){ var wf = getWeatherForecast(t.d); if (!wf) return ''; var snowInfo = wf.snow ? ' · ❄️ ' + wf.snowfall + 'мм' : ''; return ' (прогноз: ' + wf.temp + '°C · ' + wf.desc + snowInfo + ')'; })() + '</b>' : '') +
      (w && w.equipment && w.equipment !== '—' ? '<br>🚜 Техника: ' + esc(w.equipment) : '') +
      '<br>Мастер: ' + esc(m ? m.name : '?') + ' · ' + statusLabel(t) + '<br>' + dlTxt + ' · план: ' + fmtShort(t.d);
    tip.style.display = 'block';
    var x = e.clientX + 14, y = e.clientY + 14;
    if (x + 270 > window.innerWidth) x = e.clientX - 270;
    tip.style.left = x + 'px'; tip.style.top = y + 'px';
  }
  function findTask(id) { for (var i = 0; i < S.tasks.length; i++) if (S.tasks[i].id === id) return S.tasks[i]; return null; }

  /* =====================================================================
     ЯДРО: "ОПТИМИЗАТОР"
     ===================================================================== */
  function optimizeWorksCalendar() {
    var edits = 0;
    var masters = visibleMasters();
    
    masters.forEach(function (m) {
      var mTasks = S.tasks.filter(function (t) { return t.m === m.id && !isDone(t); });
      if (!mTasks.length) return;

      mTasks.sort(function (a, b) {
        if (a.dl !== b.dl) return a.dl - b.dl;
        if (a.d !== b.d) return a.d - b.d;
        return taskHours(b) - taskHours(a);
      });

      var dayLoad = {};
      S.tasks.forEach(function (t) {
        if (t.m === m.id && isDone(t)) {
          var dOff = Math.max(0, t.d);
          dayLoad[dOff] = (dayLoad[dOff] || 0) + taskHours(t);
        }
      });

      mTasks.forEach(function (t) {
        var h = taskHours(t);
        var prefDay = Math.max(0, t.d);
        
        var bestDay = null;
        var minPenalty = Infinity;
        
        for (var d = 0; d <= 90; d++) {
          var curLoad = dayLoad[d] || 0;
          if (curLoad > 0 && curLoad + h > masterCapacity(m.id, d)) continue;
          if (curLoad + h > masterCapacity(m.id, d) && curLoad > 0) continue;
          
          var penalty = Math.abs(d - prefDay) * 10;
          
          if (d > t.dl) {
            penalty += (d - t.dl) * 10000 + 50000;
          }
          if (d > prefDay) {
            penalty += 5;
          }
          
          if (penalty < minPenalty) {
            minPenalty = penalty;
            bestDay = d;
          }
        }
        
        if (bestDay === null) {
          for (var d = 0; d <= 90; d++) {
            if (!(dayLoad[d] > 0)) { bestDay = d; break; }
          }
          if (bestDay === null) bestDay = prefDay;
        }

        if (t.d !== bestDay) {
          t.d = bestDay;
          edits++;
        }
        
        if (t.dl < bestDay || t.dl < 0) {
          t.dl = Math.max(bestDay, 0);
          edits++;
        }

        dayLoad[bestDay] = (dayLoad[bestDay] || 0) + h;
        if (TASKS_DB) { TASKS_DB.updateTask(t.id, t); }
      });
    });

    toast('ok', '⚡ Оптимизация работ выполнена: распределено без просрочек с соблюдением 8-часового рабочего дня.');
    refresh();
  }
  function autoSchedule() { optimizeWorksCalendar(); }

