      var lat = (o && o.lat != null) ? o.lat : ((t.lat != null) ? t.lat : null);
      var lng = (o && o.lng != null) ? o.lng : ((t.lng != null) ? t.lng : null);
      var travelMin = t.travelMin != null ? t.travelMin : null;
